(11, 'Custom Web Development Service', 'Description Goes here', 0.00, NULL, NULL, NULL, 1, NULL, 'other', NULL),
(22, 'Web Hosting 10000', '<ul>\r\n<li>Web Hosting 10,000 MB</li>\r\n<li>Bandwidth: 100,000 MB Per month</li>\r\n<li>Languages Support: PHP, Java</li>\r\n<li>Database: MYSQL (Unlimited Databases)</li>\r\n<li>Number of Emails: Unlimited</li>\r\n</ul>', 165.00, NULL, NULL, NULL, 4, NULL, 'other', NULL),
(2, 'Logo Design', '<ul>\r\n<li>Professional Logo Designing</li>\r\n<li><span style=\"font-size: 10pt;\">High resolution file format</span></li>\r\n<li><span style=\"font-size: 10pt;\">7 Unique Logo Design Concepts to Choose from</span></li>\r\n<li><span style=\"font-size: 10pt;\">7 Logo Designers will work on the Project</span></li>\r\n<li><span style=\"font-size: 10pt;\">Unlimited Revisions till you 100% Satisfied</span></li>\r\n<li><span style=\"font-size: 10pt;\">No Clipart Used</span></li>\r\n<li><span style=\"font-size: 10pt;\">2 Redraws</span></li>\r\n</ul>\r\n<p>- Fully Copyright</p>', 2000.00, NULL, NULL, NULL, 1, NULL, 'other', NULL),
(3, 'Domain Registration / Renewal ', '<p>www.DomainName.com</p>', 100.00, NULL, NULL, '', 12, 0.00, 'domain', NULL),
(5, 'Email Hosting', '<p>Unlimited Emails Hosting Each Email will have 2GB State of the Art Infrastructure Easy to Use Web Mail Integrated with Social Media Anti Virus &amp; SPAM Control</p>', 3600.00, NULL, NULL, NULL, 4, NULL, 'other', NULL),
(7, 'Web Hosting 100', 'Web Hosting 100 MB\r\nLanguages Support: PHP, Java\r\nDatabase: MYSQL (1)\r\nNumber of Emails: 5', 35.00, NULL, NULL, NULL, 4, NULL, 'other', NULL),
(8, 'Google Apps Integration', 'DNS Hosting\r\nDNS Settings for Google Apps Integration', 1000.00, NULL, NULL, NULL, 4, NULL, 'other', NULL),
(9, 'Web Hosting 1000', '<ul>\r\n<li>Web Hosting 1000 MB</li>\r\n<li>Bandwidth: 10,000 MB Per month</li>\r\n<li>Languages Support: PHP, Java</li>\r\n<li>Database: MYSQL (2 Databases)</li>\r\n<li>Number of Emails: 20</li>\r\n</ul>', 75.00, NULL, NULL, NULL, 4, NULL, 'other', NULL),
(21, 'Web Hosting 200', '<ul>\r\n<li>Web Hosting 200 MB</li>\r\n<li>Bandwidth: 2,000 MB Per month</li>\r\n<li>Languages Support: PHP, Java</li>\r\n<li>Database: MYSQL (1 Databases)</li>\r\n<li>Number of Emails: 10</li>\r\n</ul>', 50.00, NULL, NULL, NULL, 4, NULL, 'other', NULL),
(20, 'Web Hosting 500', '<ul>\r\n<li>Web Hosting 500 MB</li>\r\n<li>Bandwidth: 2,000 MB Per month</li>\r\n<li>Languages Support: PHP, Java</li>\r\n<li>Database: MYSQL (1 Databases)</li>\r\n<li>Number of Emails: 15</li>\r\n</ul>', 60.00, NULL, NULL, NULL, 4, NULL, 'other', NULL),
(16, 'Email Marketer Software', '<ul>\r\n<li>High Class Hosted Email Marketing Software</li>\r\n<li>Unlimited Contact Lists, Segmentation</li>\r\n<li>Integration with Website for Newsletter Subscription</li>\r\n<li>Custom Fields</li>\r\n<li>50+ Newsletter Templates -</li>\r\n<li>Bounce Handling and Subscription Management</li>\r\n<li>Surveys and Auto Respondents&nbsp;</li>\r\n<li>Full Campaign Statistics (Open, Clicks, forwards and Bounce)</li>\r\n</ul>', 250.00, NULL, NULL, NULL, 1, NULL, 'other', NULL),
(23, 'Web Designing (CMS)', '<ul>\r\n<li>Graphically Rich web Design With Jquery Banners (English)</li>\r\n<li>Powerful CMS.</li>\r\n<li>Add/Edit/Delete Unlimited Pages and add Unlimited Pictures</li>\r\n<li>Complete Structure will be developed as per the Sitemap provided</li>\r\n<li>Video&nbsp;Enabled&nbsp;</li>\r\n<li>Specialized Media Pages with News Updating Facility</li>\r\n<li>Dynamic Picture Gallery&nbsp;</li>\r\n<li>Social Media Sharing (Facebook Share, Like, Twitter, etc)</li>\r\n<li>SEO Friendly</li>\r\n<li>High class XHTM Standard based development allows future extendibility of features easy</li>\r\n<li>Cross-Browser compatibility</li>\r\n<li>Cross-Device Compatibility</li>\r\n<li>CMS support Adding New features fast and easy</li>\r\n</ul>', 6500.00, NULL, NULL, NULL, 1, NULL, 'other', NULL),
(18, 'Search Engine Optimization (SEO)', '<p>- Free Home Page Search Engine Optimization - Title Tag, Description, Keywords, and Author Tag - Free Search Engine Submission (Google, Yahoo and Bing) - Monthly Packages for On-going and Off-Page SEO are available</p>', 0.00, NULL, NULL, '', 51, 0.00, 'other', NULL),
(19, 'Web Hosting 5000', '<ul>\r\n<li>Web Hosting 5000 MB</li>\r\n<li>Bandwidth: 50,000 MB Per month</li>\r\n<li>Languages Support: PHP, Java</li>\r\n<li>Database: MYSQL (5 Databases)</li>\r\n<li>Number of Emails: 50</li>\r\n</ul>', 125.00, NULL, NULL, NULL, 4, NULL, 'other', NULL),
(24, 'E-Marketer Newsletter Software', '<p>- Unlimited Lists<br />- Unlimited Segmentation<br />- Email Newsletter Designer<br />- Email Newsletter Templates<br />- Complete Statistics<br />- Surveys<br />- Bounce/Subscription Handling</p>', 3500.00, NULL, NULL, NULL, 3, NULL, 'other', NULL),
(25, 'Email Hosting & SMTP Services', '<ul>\r\n<li>Email Software Hosting</li>\r\n<li>10,000 Email Relays Per month</li>\r\n</ul>', 300.00, NULL, NULL, NULL, 4, NULL, 'other', NULL),
(26, 'CD Catalogue', '<ul>\r\n<li>HTML Website to run Offline without Server</li>\r\n<li>Multi-Category Structure for Products</li>\r\n<li>Auto Run On CD/USB</li>\r\n<li>Flash Splash Screen</li>\r\n</ul>', 5000.00, NULL, NULL, NULL, 1, NULL, 'other', NULL),
(27, 'Stationary Designing', '<ul>\r\n<li><span>Envelop.</span></li>\r\n<li><span>Notepad.</span></li>\r\n<li><span>Letter head.</span></li>\r\n<li><span>Invoice.</span></li>\r\n<li><span>Delivery Order.</span></li>\r\n<li><span>Debit/Credit Vouchers</span></li>\r\n</ul>', 2000.00, NULL, NULL, NULL, 1, NULL, 'other', NULL),
(28, 'E-Commerce Web Development', '<p><strong>- Professionally Designed Store Front with Jquery Banner</strong><strong><br /> <strong>- Mobile Friendly</strong></strong></p>\r\n<p><strong><span style=\"text-decoration: underline;\">Shopping Cart Features:</span></strong></p>\r\n<p><em>Product Catalogue:</em></p>\r\n<ul>\r\n<li>Unlimited Products, Unlimited Categories/Sub Categories Structure</li>\r\n<li>Unlimited Pictures Per Product, Zooming, etc</li>\r\n<li>Separate Meta Tags (Title, Description, Keywords) for each Product</li>\r\n<li>Unlimited Attributes Per Product (Color, Size, etc)</li>\r\n<li>Basic Inventory Management</li>\r\n<li>Integration with eBay, Amazon, Google Shopping and more*</li>\r\n<li>Cross Selling, Up Selling</li>\r\n<li>Products Comparison*</li>\r\n<li>Product Reviews, Tell a Friend and Wish List*</li>\r\n<li>Layered Navigation</li>\r\n<li>Advanced Stock Management*</li>\r\n</ul>\r\n<p><em>Shopping Cart:</em></p>\r\n<ul>\r\n<li>Simple and Easy to Use Order Process</li>\r\n<li>Customer Account or Checkout as guest</li>\r\n<li>One Page Checkout</li>\r\n<li>Gift Messages / Gift Wrapping</li>\r\n</ul>\r\n<p><em>Powerful Shipping Handling:</em></p>\r\n<ul>\r\n<li>Shipping Discounts</li>\r\n<li>Automatic Shipping Calculation by Price or Weight, Zone</li>\r\n<li>Integration with UPS, FedEx</li>\r\n<li>Unlimited Carriers and Destinations</li>\r\n</ul>\r\n<p><em>Payment Gateway:</em></p>\r\n<ul>\r\n<li>Multi Payment Gateway</li>\r\n<li>Integration with Paypal, 2CO, Cash On Delivery</li>\r\n<li>Additional Payment Gateways*</li>\r\n</ul>\r\n<p><em>Order Management &amp; Customer Handling</em></p>\r\n<ul>\r\n<li>Complete Customer Account</li>\r\n<li>Email Notifications to Customers for Change in Order Status</li>\r\n<li>Return Management</li>\r\n<li>Customer Can Track His Order</li>\r\n<li>Complete Statistics</li>\r\n</ul>\r\n<p><em>General Features:</em></p>\r\n<ul>\r\n<li>Multi User Secure Environment</li>\r\n<li>Multi Lingual*</li>\r\n<li>Multi Currency</li>\r\n<li>Multi Store</li>\r\n<li>CRM, ERP Integration*</li>\r\n<li>Simple to use CMS</li>\r\n<li>SEO Friendly (Meta, URLs, Sitemaps)</li>\r\n</ul>\r\n<p>*Extra Cost Items</p>', 8500.00, NULL, NULL, NULL, 1, NULL, 'other', NULL),
(29, 'Custom Web Hosting', '', 0.00, NULL, NULL, NULL, 4, NULL, 'other', NULL),
(30, 'Windows Hosting - 500', '<ul>\r\n<li>Web Hosting 500 MB</li>\r\n<li>Bandwidth: 5,000 MB Per month</li>\r\n<li>Languages Support: ASP, ASP.net, Java</li>\r\n<li>Database: SQL Server, MS Access</li>\r\n<li>Number of Emails: 10</li>\r\n</ul>', 750.00, NULL, NULL, NULL, 4, NULL, 'other', NULL),
(31, 'Deduction', '<p>Description</p>', 1.00, NULL, NULL, NULL, 1, NULL, 'other', NULL),
(32, 'Small Business Starter Website', '<p>- Small Business Modren Style Static Website</p>\r\n<p>- 5 Pages (Home, About Us, Products &amp; Services, Contact Us)</p>\r\n<p>- Jquery Banner (3 Slides Max)</p>\r\n<p>- SEO Friendly</p>\r\n<p>- Mobile Friendly</p>\r\n<p>- Additional Pages Charges: 200 Dhs Per Page</p>', 1500.00, NULL, NULL, NULL, 1, NULL, 'other', NULL),
(33, 'Printing', '', 0.00, NULL, NULL, NULL, 8, NULL, 'other', NULL),
(34, 'Search Engine Optimization (SEO) - Business Starter Package', '<p>- Upload 10 key indexable phrases that you choose to market your business. - Analyze your competition. - Examine the structure and content of your Web site. - Create and upload search-engine friendly meta data. - Provide a comprehensive SEO analysis of your site. - Deliver support to discuss the present and future of your Web site. - Submit your site to up to 100 search engines and directories. - Submission of Press Releases - Submission of Articles to Web 2.0 Properties - Google & Yahoo Site Maps Creation & Submission - Both IN-Page and Off-Page SEO - Competitor Analysis, and Regular steps to increase PR of Site - Monitor traffic using the latest SEO technology. - Site Map Submissions to Google/Yahoo/MSN - Robot.txt Optimization - Social Bookmarking - Content Optimization</p> \r\n<p><strong>Monthly Web Audit</strong> - Competition Analysis & Re-Adjustment of On-Page Optimization - Keyword Ranking Report - Link Analysis Report - Web Traffic Report</p> \r\n<p>Min. 1 Year Contract</p>', 3500.00, NULL, NULL, '', 51, 0.00, 'other', NULL),
(35, 'Career Portal', '<p><strong>Career Portal</strong></p>\r\n<p>&nbsp;</p>\r\n<ol>\r\n<li>Publish Unlimited Jobs</li>\r\n<li>Candidates can browse jobs and Apply for jobs</li>\r\n<li>Candidates can upload CVs</li>\r\n<li>HR Admin with separate user/Pwd</li>\r\n<li>HR Admin can see and download CVs of Candidates who applied for specific job</li>\r\n<li>HR Admin can export all data in Excel</li>\r\n</ol>\r\n<p>&nbsp;</p>', 2500.00, NULL, NULL, NULL, 1, NULL, 'other', NULL),
(36, 'AMC- Annual Maintains Contract.', '<p><span>AMC- Annual Maintains Contract.</span><br /><span>We can Add/ Edit In formations once a Month (12 Time a Year Maximum).</span><br /><span>Any Additions or Changes will be done on request.</span><br /><span>Structure of the Website will not be the Part of Contract.</span><br /><span>Content Include text and Pictures will be change able.</span></p>', 1500.00, NULL, NULL, NULL, 4, NULL, 'other', NULL),
(37, 'Arabic (RTL) Template', '<p><strong>Arabic (RTL) Template:</strong></p>\r\n<ul>\r\n<li>RTL Templateto support Arabic &amp; Other Languages from Right to Left</li>\r\n</ul>', 2500.00, NULL, NULL, NULL, 1, NULL, 'other', NULL),
(38, 'Customer Review System', '<p><strong>Customer Review System:</strong></p>\r\n<ul>\r\n<li>Allows customer to add reviews to product</li>\r\n<li>Admin can moderate customer comments</li>\r\n<li>Benefited for Better Search Engine optimization by adding user generated contents</li>\r\n</ul>', 550.00, NULL, NULL, NULL, 9, NULL, 'other', NULL),
(39, 'Youtube API Integration', '<p><strong>Youtube API Integration:</strong></p>\r\n<ul>\r\n<li>API Integration with youtube channel</li>\r\n<li>All video from youtube channel will be shown on the website</li>\r\n<li>When a new video or videos uploaded on youtube it will automatically show it on the website</li>\r\n<li>Comments on vidoes from website will be integrated with facebook page.\r\n<ul>\r\n<li>when a visitor comments on the video on website it will be shown on the facebook.</li>\r\n</ul>\r\n</li>\r\n</ul>', 4500.00, NULL, NULL, NULL, 1, NULL, 'other', NULL),
(40, 'E-Mail Marketing Campaign', '<p>- Customized email Brocheur/ Email Message will be designed</p>\r\n<p>- Message will be sent to more tha 100000 verified email address</p>\r\n<p>- Complete reporting of campaign will be given to customer</p>\r\n<p>- One Shot email campaign</p>', 2000.00, NULL, NULL, NULL, 3, NULL, 'other', NULL),
(41, 'Facebook E-Commerce Tab (E-Commerce Addon)', '<p><strong>Facebook Integration Features</strong></p>\r\n<ul>\r\n<li>Facebook Application integrated with main Website</li>\r\n<li>Facebook Login Integration</li>\r\n<li>User can buy products in facebook</li>\r\n<li>User can see their account details,order details in facebook</li>\r\n<li>Login with facebook in your main site as well as in facebook application</li>\r\n<li>Publish to your wall</li>\r\n<li>Facebook Like</li>\r\n<li>Facebook Comment</li>\r\n<li>Invite friends to your store</li>\r\n<li>Enjoy exciting features of OpenCart/JooCart in Facebook</li>\r\n<li>vQmod and no vQmod both version are included</li>\r\n<li>Options for left/right column</li>\r\n<li>Multistored*</li>\r\n<li>Options for changing color of template</li>\r\n<li>Options for automatic registration</li>\r\n</ul>', 6000.00, NULL, NULL, NULL, 1, NULL, 'other', NULL),
(42, 'Social Media Startup - 1', '<p><strong>Facebook, Google Plus &amp; Pinterest</strong></p>\r\n<p>A Perfect Package for Starters includes:</p>\r\n<p><strong>Facebook:</strong></p>\r\n<ul>\r\n<li>Facebook Page Creation</li>\r\n<li>Brand Optimized Profile Picture and Header</li>\r\n<li>Integration with Blog if any</li>\r\n<li>First 100 Fans</li>\r\n<li>Branded URL <span>e.g. facekook.com/yourbrand</span></li>\r\n<li>First 5 Posts</li>\r\n</ul>\r\n<p><strong>Google Plus:</strong></p>\r\n<ul>\r\n<li>Google Plus Page Creation</li>\r\n<li>Brand Optimized Profile Picture and header</li>\r\n<li>First 5 Posts</li>\r\n<li>25 Google Plus</li>\r\n</ul>\r\n<p><strong>Pinterest:</strong></p>\r\n<ul>\r\n<li>Profile Creation</li>\r\n<li>3 Boards creation</li>\r\n<li>Following 100 Targeted users</li>\r\n</ul>\r\n<p><strong>Note</strong>: All of this activity is done by a Marketing specialist after research related to client business and activities.</p>\r\n<p><strong>Delivery Time:</strong> 15 Days, Facebook Fans are delivered in 30 Days</p>', 3800.00, NULL, NULL, NULL, 1, NULL, 'other', NULL),
