(75, 'Tourism Website', '<p>Contemporary and Sleek Design with HTML5 and jQuery<br /><span style=\"font-size: 10pt;\">Fully Responsive and Mobile Ready<br />Fully Dynamic<br />Powerful Content Management System (CMS)<br />SEO Friendly</span></p>\r\n<p><strong><span style=\"font-size: 10pt;\">Features:</span></strong></p>\r\n<p><strong><span style=\"font-size: 10pt;\">Tours &amp; Packages<br /><br /></span></strong></p>\r\n<ul>\r\n<li><span style=\"font-size: 10pt;\">Unlimited Tours BY Destination City or Activity Type</span></li>\r\n<li><span style=\"font-size: 10pt;\">Tour Detail Page</span></li>\r\n<li><span style=\"font-size: 10pt;\">Image Gallery / Video Attached with each Tour</span></li>\r\n<li><span style=\"font-size: 10pt;\">Tour Guide<br /></span></li>\r\n<li><span style=\"font-size: 10pt;\">Tour Rating System*</span></li>\r\n</ul>\r\n<p><strong><span style=\"font-size: 10pt;\">Booking &amp; Management:</span></strong></p>\r\n<p>&nbsp;</p>\r\n<ul>\r\n<li>Powerful Booking Form with Date of Booking and Number of Persons</li>\r\n<li>Order Management / Shopping Cart Integration&nbsp;</li>\r\n<li>Payment Gateway Integration (Paypal, and One Local Gateway)</li>\r\n</ul>', 16500.00, NULL, NULL, NULL, 1, NULL, 'other', NULL),
