(3048, 115, 'proposal', 'Search Engine Optimization (SEO) - Business Starter Package', '<p>- Upload 10 key indexable phrases that you choose to market your business.<br />\r\n- Analyze your competition.<br />\r\n- Examine the structure and content of your Web site.<br />\r\n- Create and upload search-engine friendly metadata.<br />\r\n- Provide a comprehensive SEO analysis of your site.<br />\r\n- Deliver support to discuss the present and future of your Web site.<br />\r\n- Submit your site to up to 100 search engines and directories.<br />\r\n- Submission of Press Releases<br />\r\n- Submission of Articles to Web 2.0 Properties<br />\r\n- Google & Yahoo Site Maps Creation & Submission <br />\r\n- Both IN-Page and Off-Page SEO<br />\r\n- Competitor Analysis, and Regular steps to increase PR of Site<br />\r\n - Monitor traffic using the latest SEO techniques. <br />\r\n- Site Map Submissions to GoogleOptimization<br />\r\n - Social Bookmarking<br />\r\n - Content Optimization</p><br />\r\n<p><strong>Monthly Web Audit<br />\r\n<br />\r\n</strong> - Competition Analysis & Re-Adjustment of On-Page Optimization<br />\r\n - Keyword Ranking Report<br />\r\n - Link Analysis Report<br />\r\n - Web Traffic Report</p><br />\r\n<p>Min. 1 Year Contract</p>', 1.00, 2500.00, '', 2, '0000-00-00', '0000-00-00', '0', 0, NULL, NULL, 0, '', 0, 'Y', '0', '0', '0', '0', 'other', ''),
(3049, 115, 'proposal', 'Google Adwords', 'Google Adwords Campaign Management<br />\r\n<br />\r\n<br />\r\n<ul><br />\r\n<li><span>Complete Google Adwords account and campaign creation, maintenance, consultation and reporting</span></li><br />\r\n<li><span>Keywords </span>Suggestions<span style=\"font-size: 12pt;\"> </span></li><br />\r\n<li><span style=\"font-size: 12pt;\">Service charges 1000 AED or 10% of the total budget whichever is higher</span></li><br />\r\n<li><span style=\"font-size: 12pt;\"> Google Payment (Monthly Suggested) 2000 AED minimum</span></li><br />\r\n</ul>', 1.00, 4000.00, '', 3, '0000-00-00', '0000-00-00', '0', 0, NULL, NULL, 0, '', 0, 'Y', '0', '0', '0', '0', 'other', ''),
(3050, 115, 'proposal', 'Photography', '<strong>Professional Photography<br />\r\n</strong><br />\r\n<br />\r\n<ul><br />\r\n<li><span>All photos will be provided in TIFF & RAW format </span><span>(also can be provided as per requirement)</span></li><br />\r\n<li>We charge AED. 500/Hour for Corporate Events Photography</li><br />\r\n</ul>', 1.00, 500.00, '', 4, '0000-00-00', '0000-00-00', '0', 0, NULL, NULL, 0, '', 0, 'Y', '0', '0', '0', '0', 'other', ''),
(3051, 4, 'estimate', 'Web Designing (CMS)', '<ul><br />\r\n<li>Graphically Rich web Design With Jquery Banners (English)</li><br />\r\n<li>Powerful CMS.</li><br />\r\n<li>Add/Edit/Delete Unlimited Pages and add Unlimited Pictures</li><br />\r\n<li>Complete Structure will be developed as per the Sitemap provided</li><br />\r\n<li>Video Enabled </li><br />\r\n<li>Specialized Media Pages with News Updating Facility</li><br />\r\n<li>Dynamic Picture Gallery </li><br />\r\n<li>Social Media Sharing (Facebook Share, Like, Twitter, etc)</li><br />\r\n<li>SEO Friendly</li><br />\r\n<li>High-class XHTML Standard based development allows future extendibility of features easy</li><br />\r\n<li>Cross-Browser compatibility</li><br />\r\n<li>Cross-Device Compatibility</li><br />\r\n<li>CMS support Adding New features fast and easy</li><br />\r\n</ul>', 1.00, 9000.00, '', 1, '1970-01-01', '1970-01-01', '', 0, NULL, NULL, 0, '', 0, 'Y', '0', '0', '0', '0', 'other', ''),
