(3812, 240, 'proposal', 'Recruitment Web Portal', '<p><strong>General Features:</strong></p><br />\r\n<ul><br />\r\n<li>Graphically Rich web Design With Banners (English/Arabic)</li><br />\r\n<li><span xss=removed>Powerful CMS.</span></li><br />\r\n<li><span xss=removed>Add/Edit/Delete Unlimited Pages and add Unlimited Pictures</span></li><br />\r\n<li><span xss=removed>Complete Structure will be developed as per the Sitemap provided</span></li><br />\r\n<li><span xss=removed>Video Enabled</span></li><br />\r\n<li><span xss=removed>Specialized Media Pages with News Updating Facility</span></li><br />\r\n<li><span xss=removed>Dynamic Picture Gallery</span></li><br />\r\n<li><span xss=removed>Social Media Sharing (Facebook Share, Like, Twitter, etc)</span></li><br />\r\n<li><span xss=removed>SEO Friendly</span></li><br />\r\n<li><span xss=removed>High class XHTM Standard based development allows future e</span><span xss=removed>xtendibility of features easy</span></li><br />\r\n<li><span xss=removed>Cross-Browser compatibility</span></li><br />\r\n<li><span xss=removed>Cross-Device Compatibility</span></li><br />\r\n<li><span xss=removed>CMS support Adding New features fast and easy</span></li><br />\r\n</ul>', 2.00, 9000.00, '', 1, '0000-00-00', '0000-00-00', '0', 0, NULL, NULL, 0, '', 0, 'Y', '0', '0', '0', '0', 'other', ''),
(3808, 2121, 'invoice', 'Google Adwords', '<p>Google Adwords Campaign Management</p><br />\r\n<ul><br />\r\n<ul><br />\r\n<li>Keyword\'s research adding new and removing low performing keywords</li><br />\r\n</ul><br />\r\n</ul><br />\r\n<br />\r\n<br />\r\n<ul><br />\r\n<ul><br />\r\n<li>Adding new Ad copies in the multiple Ad groups</li><br />\r\n</ul><br />\r\n</ul><br />\r\n<br />\r\n<br />\r\n<ul><br />\r\n<ul><br />\r\n<li>Changing Adwords strategy to increase the total number of clicks for. e.g; long tail keywords, short phrase keywords, exact match, broad match or broad match modifier.</li><br />\r\n</ul><br />\r\n</ul><br />\r\n<br />\r\n<br />\r\n<ul><br />\r\n<ul><br />\r\n<li>Daily monitoring the campaign and monthly progress report generation</li><br />\r\n</ul><br />\r\n</ul><br />\r\n<br />\r\n<br />\r\n<ul><br />\r\n<li>Always supporting the client to the best of our research and expertise level.</li><br />\r\n</ul><br />\r\nTarget Countries:<br />\r\n<br />\r\n1. KSA<br />\r\n2. UAE', 1.00, 1000.00, '', 1, '2018-09-01', '2018-10-01', '1', 0, NULL, NULL, 0, '', 0, 'Y', '0', '0', '0', '0', 'other', ''),
