(202, 'email_footer', '</td>\r\n                       </tr>\r\n                     </table>\r\n                   </td>\r\n                 </tr>\r\n                 <!-- END MAIN CONTENT AREA -->\r\n               </table>\r\n               <!-- START FOOTER -->\r\n               <div class=\"footer\">\r\n                <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n                  <tr>\r\n                    <td class=\"content-block\">\r\n                      <span>{companyname}</span>\r\n                    </td>\r\n                  </tr>\r\n                </table>\r\n              </div>\r\n              <!-- END FOOTER -->\r\n              <!-- END CENTERED WHITE CONTAINER -->\r\n            </div>\r\n          </td>\r\n          <td>&nbsp;</td>\r\n        </tr>\r\n      </table>\r\n    </body>\r\n    </html>', 1),
