INSERT INTO `tblsalesactivity` (`id`, `rel_type`, `rel_id`, `description`, `additional_data`, `staffid`, `full_name`, `date`) VALUES
(5603, 'invoice', 2615, 'invoice_estimate_activity_updated_item_long_description', 'a:2:{i:0;s:1961:\"<p><strong>Website Speed Optimization</strong></p><br />\r\n<ul><br />\r\n<li>Complete Optimization to make Google Speed Score to 75+</li><br />\r\n<li>Minifying and Optimization of Scripts</li><br />\r\n<li>Images Optimization</li><br />\r\n<li>Cache Handling</li><br />\r\n<li>Bi-Monthly Tests</li><br />\r\n<li>*In case of Slow Hosting, Hosting may have to be changed</li><br />\r\n</ul><br />\r\n<p><strong>Secure Socket Layer (SSL)</strong></p><br />\r\n<ul><br />\r\n<li>Implementation and Maintenance</li><br />\r\n<li>*In Case Hosting doesn\'t support, it may have to be changed.</li><br />\r\n</ul><br />\r\n<p><strong>Website Maintenance Services</strong></p><br />\r\n<ul><br />\r\n<li>Backup Frequency: Monthly (Offline)</li><br />\r\n<li>CMS Updates (As Available) : Monthly</li><br />\r\n<li>Backup is Maintained <g class=\"gr_ gr_59 gr-alert gr_gramm gr_inline_cards gr_run_anim Punctuation only-del replaceWithoutSep\" id=\"59\" data-gr-id=\"59\"><g class=\"gr_ gr_57 gr-alert gr_spell gr_inline_cards gr_disable_anim_appear ContextualSpelling ins-del multiReplace\" id=\"57\" data-gr-id=\"57\">upto</g>:</g>     3 Months</li><br />\r\n<li>Plugins Updates (As Available)</li><br />\r\n<li>Theme Updates whenever necessary with update in CMS</li><br />\r\n</ul><br />\r\n<p><strong>Design/Update Services: </strong> (1 Hour Monthly)</p><br />\r\n<ul><br />\r\n<li>New Banners</li><br />\r\n<li>Product changes or additions</li><br />\r\n<li>Updates to calendar or upcoming events</li><br />\r\n<li>Post job opportunities</li><br />\r\n<li>Photos, graphics, graphs, and charts updated</li><br />\r\n<li>Text re-writes or edits</li><br />\r\n<li>Site facelifts and makeovers</li><br />\r\n<li>-Bugs Removal</li><br />\r\n</ul><br />\r\n<p><strong>Regular Turn Around Time:    </strong>48 Hours<strong>Emergency Turn Around Time:   </strong>12 Hours</p><br />\r\n<p>- Additional Hours Of Design & Maintenance: 110 Dhs Per Hour - - - Additional Hours Of Development: 185 Dhs Per Hour</p><br />\r\n<p> </p><br />\r\n<p> </p>\";i:1;s:1679:\"<p><strong>Website Speed Optimization</strong></p>\r\n<ul>\r\n<li>Minifying and Optimization of Scripts</li>\r\n<li>Images Optimization</li>\r\n<li>Cache Handling</li>\r\n<li>Bi-Monthly Tests</li>\r\n<li>*In case of Slow Hosting, Hosting may have to be changed</li>\r\n</ul>\r\n<p><strong>Secure Socket Layer (SSL)</strong></p>\r\n<ul>\r\n<li>Implementation and Maintenance</li>\r\n<li>*In Case Hosting doesn\'t support, it may have to be changed.</li>\r\n</ul>\r\n<p><strong>Website Maintenance Services</strong></p>\r\n<ul>\r\n<li>Backup Frequency: Monthly (Offline)</li>\r\n<li>CMS Updates (As Available) : Monthly</li>\r\n<li>Backup is Maintained <g class=\"gr_ gr_59 gr-alert gr_gramm gr_inline_cards gr_run_anim Punctuation only-del replaceWithoutSep\" id=\"59\" data-gr-id=\"59\"><g class=\"gr_ gr_57 gr-alert gr_spell gr_inline_cards gr_disable_anim_appear ContextualSpelling ins-del multiReplace\" id=\"57\" data-gr-id=\"57\">upto</g>:</g>     3 Months</li>\r\n<li>Plugins Updates (As Available)</li>\r\n<li>Theme Updates whenever necessary with update in CMS</li>\r\n</ul>\r\n<p><strong>Design/Update Services: </strong> (1 Hour Monthly)</p>\r\n<ul>\r\n<li>New Banners</li>\r\n<li>Product changes or additions</li>\r\n<li>Updates to calendar or upcoming events</li>\r\n<li>Post job opportunities</li>\r\n<li>Photos, graphics, graphs, and charts updated</li>\r\n<li>Text re-writes or edits</li>\r\n<li>Site facelifts and makeovers</li>\r\n<li>-Bugs Removal</li>\r\n</ul>\r\n<p><strong>Regular Turn Around Time:    </strong>48 Hours<strong>Emergency Turn Around Time:   </strong>12 Hours</p>\r\n<p>- Additional Hours Of Design & Maintenance: 110 Dhs Per Hour - - - Additional Hours Of Development: 185 Dhs Per Hour</p>\r\n<p> </p>\r\n<p> </p>\";}', '1', 'Khuram Iqbal', '2019-07-20 22:42:54'),
