(45, 45, 1016, 496, NULL, NULL, '2018-07-03 15:45:13', 'Add for Zaid Only to test', NULL, NULL, '94.200.112.14'),
(46, 25, 0, 0, NULL, NULL, '2018-07-04 10:30:06', '<p>Done!</p>\r\n<p>Now docs can be searched by username and company&nbsp;name</p>', NULL, 22, '94.200.112.14'),
(47, 20, 0, 0, NULL, NULL, '2018-07-04 10:35:50', 'The maximum size for news title is 500 characters in the backend, here only 40 characters are shown so it cannot be always sure that complete title would appear here or not so we used ... to indicate that title is continued. Similarly for the description', NULL, 22, '94.200.112.14'),
(48, 16, 0, 0, NULL, NULL, '2018-07-04 10:37:51', 'We are currently working on it to make sure on small devices it works perfectly', NULL, 22, '94.200.112.14'),
